update pages set contenu = '{"gabarit":"fiche","chapeau":"STELLANTIS, anciennement PSA, a retenu Migen comme partenaire pour plusieurs de ses sites du Grand Est, depuis juin 2023. La décision s''inscrit dans la transition de ses usines vers la production de véhicules électriques.","fiche":[],"contexte":"**Faire basculer des usines vers l''électrique demande des compétences que les équipes en place n''ont pas toutes.** Le problème n''est pas d''ajouter des heures, il est d''ajouter des compétences absentes en interne.\nLa problématique posée : un manque de compétence pour prendre en charge les parcs machines de plusieurs sites, dans un contexte de transition technologique.\n**Plusieurs sites en même temps** : Le besoin ne portait pas sur une usine isolée.\n**Des compétences variées à réunir** : Du préventif au curatif, sur des équipements différents.\n**Un outil industriel mouvant** : Les parcs machines changent pendant que les usines produisent.","intervention":"**Des dizaines d''intervenants en simultané** : Plusieurs dizaines de collaborateurs aux compétences variées, mobilisés en même temps sur les sites concernés.\n**Préventif et curatif portés ensemble** : Le même dispositif couvre les deux, sans découpage artificiel entre la prévention et la réparation.\n**Une montée en charge progressive** : Le partenariat a commencé sur un périmètre réduit, puis s''est étendu après résolution des premières difficultés techniques.\n**Un engagement long** : Le contrat porte sur le développement et l''amélioration des performances, pas sur une intervention ponctuelle.\nCe qui a déclenché l''extension du périmètre : la confiance mutuelle et la capacité de Migen à traiter efficacement les premières difficultés techniques. Le besoin est passé d''un point technique à couvrir à plusieurs sites servis en parallèle.","resultats":[]}'::jsonb where path = '/preuves/stellantis-grand-est/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"STELLANTIS, anciennement PSA"},{"libelle":"Territoire","valeur":"Plusieurs sites du Grand Est"},{"libelle":"Secteur","valeur":"Industrie automobile"},{"libelle":"Démarrage","valeur":"Juin 2023, mission en cours"},{"libelle":"Effectif Migen","valeur":"18 à 25 techniciens"},{"libelle":"Problématique","valeur":"Manque de compétence sur les parcs machines en transition technologique"},{"libelle":"Réponse","valeur":"Plusieurs dizaines de collaborateurs aux compétences variées"},{"libelle":"Nature des travaux","valeur":"Maintenance préventive et curative"}]'::jsonb) where path = '/preuves/stellantis-grand-est/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Les parcs machines de plusieurs sites sont pris en charge","libelle":"Le manque de compétence initial est couvert."},{"valeur":"Le préventif et le curatif tiennent ensemble","libelle":"Un seul dispositif porte les deux."},{"valeur":"La collaboration s''est élargie dans la durée","libelle":"Site après site, sur un engagement continu."}]'::jsonb) where path = '/preuves/stellantis-grand-est/';
